// Generated by vibelang from src/main/storage/install-state.ts; the migrate flow writes it again with each batch.
export function hasExistingAppState(entries) {
    return entries.some((entry) => {
        if (entry.name === "opencode.settings")
            return true;
        if (entry.name.endsWith(".dat"))
            return true;
        if (entry.name === "drafts.sqlite")
            return true;
        if (/^window-state-.+\.json$/.test(entry.name))
            return true;
        return entry.directory && entry.name === "opencode";
    });
}
